property.value:
Resource_Avail  =  newArray (Num_Cores, true)      /* Mem1 */
Proc_Speed      =  newArray(Num_Cores,Core_Speed)    /* DS2  */

Proc_Speed(0) = Big_Core_Speed                          /* Big Core 1 */
Proc_Speed(1) = Big_Core_Speed                          /* Big Core 2 */
Proc_Speed(2) = Little_Core_Speed                       /* Little Core 3 */
Proc_Speed(3) = Little_Core_Speed                       /* Little Core 4 */
LABEL: BEGIN
if(port_name == "virtual")  
{
	Resource_Avail(port_token.Avl_Resource)= true
}	
if(getBlockStatus("Queue","length",1,1)>0  && (find(Resource_Avail)).length()>0)
{
	Next_Trans  = getBlockStatus("Queue","Take",1,1) 
	Next_Trans.Avl_Resource = (find(Resource_Avail))(0)
	Resource_Avail(Next_Trans.Avl_Resource)= false
	Next_Trans.Core_Name = toString(Next_Trans.Avl_Resource)
	Next_Trans.Processing_Time = Next_Trans.Num_Inst / Proc_Speed (Next_Trans.Avl_Resource)/1.0e6
	SEND(output,Next_Trans)
}

/* Template to enter multiple RegEx lines*/
   Result_A = MyRegExpression_A_or_None /* Expression 1 */
   Result_B = MyRegExpression_B_or_None  /* Expression 2 */
   Result_C = MyRegExpression_C_or_None /* Expression 3 */  
/* Add as many RegEx lines are required */

/* Power_Table.  First row contains Column Names, expressions valid for entries except Device Name.                                                 

--------Device Name-------  ---------Power States------  -----Operating States------  -----------State Transitions---------  --Speed--  --Exist-- */
    Architecture_Block      Standby 	   Active          Wait     Idle    Existing  OffState  OnState  t_OnOff     Mhz       Volts   ; 
Scheduler_0  BigStbyPwr    BigActPwr      0.0  0.0  Standby  Standby  Active  100.0e-9  2500.0  1.2  ;
Scheduler_1  BigStbyPwr    BigActPwr      0.0  0.0  Standby  Standby  Active  100.0e-9  2500.0  1.2  ;
Scheduler_2  LittleStbyPwr LittleActPwr   0.0  0.0  Standby  Standby  Active  100.0e-9  1000.0  0.8  ;
Scheduler_3  LittleStbyPwr LittleActPwr   0.0  0.0  Standby  Standby  Active  100.0e-9  1000.0  0.8  ;

/* Async_State_Change.  First row contains Column Names, expressions valid for entries except Device Name.                                                 

--------Device Name-------  ------------Time State--------- */
    Architecture_Block      State     Time_or_Express  Next ;

/* First row contains Column Names.                                                                                                                 

---------Reference--------  ------------------------------------Expression----------------------------------------------------------------------- */
           Name                                                   Value                                                                           ; 
Standby_Power           0.01              ;
Active_Power            Core_Power/100.0  ;
BigActPwr               Core_Power*1.4/100.0  ;
LittleActPwr            Core_Power*0.4/100.0  ;
BigStbyPwr              0.02              ;
LittleStbyPwr           0.005             ;

/* Power, Thermal. */ T_Ambient = Ambient_Temp_C // 40.0 C Theta_JC = 20.0 // junction to case C / W, estd Theta_CS = 0.8 // case to heatsink C / W, estd Theta_SA = 20.0 // heatsink to ambient C / W, estd Theta_JA = 21.62 // junction to ambient temp C / W, estd
LABEL: BEGIN Power = port_token // watts
Theta_Sum = Theta_JC + Theta_CS + Theta_SA T_Junction_Numerator = Theta_JA * Theta_Sum T_Junction_Denominator = Theta_JA + Theta_Sum T_Junction = T_Ambient+ ((T_Junction_Numerator/T_Junction_Denominator)*Power) SEND (temperature, T_Junction)
